const defaultSummaries=[[{label:'Discovery sessions',value:'1',icon:'⌕',note:'Completed this month'},{label:'Feedback interviews',value:'4',icon:'▣',note:'Customer conversations'},{label:'Key insights',value:'8',icon:'◇',note:'Validated findings'},{label:'Actionable items',value:'15',icon:'✦',note:'Ready to progress'}],[{label:'Features (WIP)',value:'30+',icon:'◇',note:'In active delivery'},{label:'Designed screens',value:'124',icon:'▣',note:'Production-ready frames'},{label:'Audits',value:'7',icon:'↗',note:'Design reviews'},{label:'New items',value:'6',icon:'◫',note:'Added this month'}],[{label:'Co-creation sessions',value:'30',icon:'◎',note:'Cross-team workshops'},{label:'Interaction flows',value:'8',icon:'◇',note:'Validated journeys'}],[{label:'AI workflows',value:'41',icon:'✦',note:'Assisted activities'},{label:'Tools and modes',value:'5',icon:'▣',note:'In active use'},{label:'Plugins',value:'3',icon:'◫',note:'Connected tools'},{label:'Skills & models',value:'8',icon:'◇',note:'Reusable capabilities'}],[{label:'Top highlights',value:'4',icon:'✦',note:'Monthly wins'},{label:'Potential risks',value:'1',icon:'△',note:'Needs attention'},{label:'Next priorities',value:'5',icon:'↗',note:'Planned focus'}]];
function makeEmptyReportSections(){return defaultSections.map((section,si)=>({...structuredClone(section),summaries:(defaultSummaries[si]||[]).map(summary=>({...structuredClone(summary),value:'0'})),cols:section.cols.map(column=>({...structuredClone(column),items:[]}))}))}
function normalizeTag(tag,index=0){return typeof tag==='string'?{name:tag,color:tagColors[index%tagColors.length]}:{name:tag.name||'',color:tagColors.includes(tag.color)?tag.color:'blue'}}
function normalizeSections(sections){sections.forEach((s,si)=>{s.summaries??=structuredClone(defaultSummaries[si]||[]);s.cols.forEach(c=>c.items.forEach(i=>{i.tags=(i.tags||[]).map(normalizeTag);i.status??='in-progress';i.details??={summary:`${i.title} brings the related work into one cohesive experience, reducing effort and making the workflow easier to understand.`,secondary:i.description||'This work is progressing through the design lifecycle with evidence linked to the source.',sourceUrl:'https://www.figma.com/',stage:3,statusNotes:[{text:i.description||'Work is in progress',tone:'neutral'},{text:'Design review is underway',tone:'neutral'}]};i.details.figmaLinks??=i.details.sourceUrl?[{title:'Figma source',url:i.details.sourceUrl}]:[]}))});return sections}
