$('#addTagButton').addEventListener('click',()=>{const form=$('#editorForm'),name=form.tagName.value.trim(),color=form.tagColor.value;if(!name){form.tagName.focus();showToast('Enter a tag name');return}draftTags.push({name,color});form.tagName.value='';renderDraftTags();form.tagName.focus()});
$('#addCustomStatusEditor').addEventListener('click',()=>addCustomStatus($('#editorForm'),$('#editorForm select[name="status"]')));
$('#addCustomStatusDetail').addEventListener('click',()=>addCustomStatus($('#detailEditForm'),$('#detailEditForm select[name="status"]')));
$('#editorForm input[name="tagName"]').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#addTagButton').click()}});
$('#tagPreview').addEventListener('click',e=>{const remove=e.target.closest('[data-draft-tag]');if(!remove)return;draftTags.splice(Number(remove.dataset.draftTag),1);renderDraftTags()});
$('#editorForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form),action=fd.get('action'),si=Number(fd.get('section')),ci=Number(fd.get('column')),ii=Number(fd.get('item')),title=fd.get('title').trim(),description=fd.get('description').trim(),tags=draftTags.map(t=>({...t})),status=fd.get('status')||'not-started';if(action==='add-section')playbackSections.push({title,sub:description,summaries:[],cols:[]});if(action==='edit-section')Object.assign(playbackSections[si],{title,sub:description});if(action==='add-column')playbackSections[si].cols.push({title,items:[]});if(action==='edit-column')playbackSections[si].cols[ci].title=title;if(action==='add-item')playbackSections[si].cols[ci].items.push({title,description,tags,status});if(action==='edit-item'||action==='edit-tags')Object.assign(playbackSections[si].cols[ci].items[ii],{title,description,tags,status});saveSections();closeEditor();showToast('Playback content saved')});
$('#bulkClear').addEventListener('click',()=>{selectedCards.clear();renderPlayback()});
$('#bulkTag').addEventListener('click',openBulkTag);
$('#bulkDelete').addEventListener('click',()=>{pendingDelete={type:'bulk'};$('#confirmTitle').textContent=`Delete ${selectedCards.size} selected cards?`;$('#confirmMessage').textContent='All selected cards and their tags will be removed. This cannot be undone.';$('#confirmModal').classList.add('open');$('#modalBackdrop').classList.add('open');$('#confirmModal').setAttribute('aria-hidden','false')});
$('#bulkTagForm input[name="name"]').addEventListener('input',e=>{$('#bulkTagPreview').textContent=e.target.value||'Tag preview'});
$('#bulkTagForm select[name="color"]').addEventListener('change',e=>{$('#bulkTagPreview').dataset.color=e.target.value});
$('#bulkTagForm').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),tag={name:fd.get('name').trim(),color:fd.get('color')};selectedEntries().forEach(({value})=>{if(!value.tags.some(t=>t.name.toLowerCase()===tag.name.toLowerCase()))value.tags.push({...tag})});saveSections();closeBulkTag();showToast(`Tag added to ${selectedCards.size} cards`)});
$('#detailEditForm').addEventListener('submit',e=>{e.preventDefault();if(!canEdit())return;const fd=new FormData(e.currentTarget),item=currentDetailItem();item.title=fd.get('title').trim();item.status=fd.get('status');Object.assign(item.details,{summary:fd.get('summary').trim(),secondary:fd.get('secondary').trim(),stage:Number(fd.get('stage'))});saveSections();closeDetailEditor();renderCardDetail();showToast('Card details updated')});
$('#summaryForm').addEventListener('submit',e=>{e.preventDefault();if(!canEdit())return;const fd=new FormData(e.currentTarget),si=Number(fd.get('section')),smi=fd.get('summary'),summary={label:fd.get('label').trim(),value:fd.get('value').trim(),icon:fd.get('icon'),note:fd.get('note').trim()};if(smi==='')playbackSections[si].summaries.push(summary);else playbackSections[si].summaries[Number(smi)]=summary;saveSections();closeSummaryEditor();showToast(smi===''?'Summary card added':'Summary card updated')});
$('#confirmDelete').addEventListener('click',()=>{if(!pendingDelete)return;const {type,section,column,item,summary}=pendingDelete;if(type==='section')playbackSections.splice(section,1);if(type==='column')playbackSections[section].cols.splice(column,1);if(type==='item')playbackSections[section].cols[column].items.splice(item,1);if(type==='summary')playbackSections[section].summaries.splice(summary,1);if(type==='bulk'){const groups={};selectedEntries().forEach(x=>{const key=`${x.section}:${x.column}`;(groups[key]??=[]).push(x.item)});Object.entries(groups).forEach(([key,indexes])=>{const[s,c]=key.split(':').map(Number);indexes.sort((a,b)=>b-a).forEach(i=>playbackSections[s].cols[c].items.splice(i,1))});selectedCards.clear()}saveSections();closeConfirm();showToast(type==='bulk'?'Selected cards deleted':type==='summary'?'Summary card deleted':'Content deleted')});

let draggedCard=null;
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-card]');if(!card||!canEdit()){e.preventDefault();return}draggedCard={section:Number(card.dataset.section),column:Number(card.dataset.column),item:Number(card.dataset.item)};card.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',JSON.stringify(draggedCard))});
document.addEventListener('dragover',e=>{if(!draggedCard)return;const column=e.target.closest('[data-drop-column]');if(!column)return;e.preventDefault();e.dataTransfer.dropEffect='move';$$('[data-drop-column].drag-over').forEach(c=>c.classList.remove('drag-over'));column.classList.add('drag-over');$$('[data-card].drop-before,[data-card].drop-after').forEach(c=>c.classList.remove('drop-before','drop-after'));const card=e.target.closest('[data-card]');if(card&&!card.classList.contains('dragging')){const before=e.clientY<card.getBoundingClientRect().top+card.offsetHeight/2;card.classList.add(before?'drop-before':'drop-after');card.dataset.dropPosition=before?'before':'after'}});
document.addEventListener('drop',e=>{if(!draggedCard)return;const column=e.target.closest('[data-drop-column]');if(!column)return;e.preventDefault();const toSection=Number(column.dataset.section),toColumn=Number(column.dataset.column),targetCard=e.target.closest('[data-card]');let toIndex=playbackSections[toSection].cols[toColumn].items.length;if(targetCard){toIndex=Number(targetCard.dataset.item)+(targetCard.dataset.dropPosition==='after'?1:0)}const source=playbackSections[draggedCard.section].cols[draggedCard.column].items;const [moved]=source.splice(draggedCard.item,1);if(draggedCard.section===toSection&&draggedCard.column===toColumn&&draggedCard.item<toIndex)toIndex--;playbackSections[toSection].cols[toColumn].items.splice(Math.max(0,toIndex),0,moved);selectedCards.clear();draggedCard=null;saveSections();showToast('Card moved')});
document.addEventListener('dragend',()=>{draggedCard=null;$$('.dragging,.drag-over,.drop-before,.drop-after').forEach(el=>el.classList.remove('dragging','drag-over','drop-before','drop-after'))});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawer();closeModal();closeProjectModal();closeEditor();closeConfirm();closeBulkTag();closeDetailEditor();closeSummaryEditor();closePresent()}if($('#presentation').classList.contains('open')&&e.key==='ArrowRight'){slide=Math.min($$('.present-slide').length-1,slide+1);updateSlide()}if($('#presentation').classList.contains('open')&&e.key==='ArrowLeft'){slide=Math.max(0,slide-1);updateSlide()}});
window.addEventListener('popstate',()=>route(location.hash.slice(1)||'overview'));
$('#roleSelect').addEventListener('change',e=>{currentRole=e.target.value;localStorage.setItem('cadence-role',currentRole);if(currentRole==='user')currentMode='view';else currentMode=localStorage.getItem('cadence-mode')||'edit';renderPlayback();applyAccess();showToast(currentRole==='admin'?'Admin profile active':'User profile · view only')});
$('#projectSelect').addEventListener('change',e=>switchProject(e.target.value));
$('#playbackSearch').addEventListener('input',e=>{playbackQuery=e.target.value;filterPlayback()});
$('#clearPlaybackSearch').addEventListener('click',()=>{$('#playbackSearch').value='';playbackQuery='';filterPlayback();$('#playbackSearch').focus()});
render();route(location.hash.slice(1)||'overview');applyAccess();
